import React from 'react';

const Results = ({ data }) => {
    if (!data || !data.content) {
        return null;
    }

    return (
        <div className="result-container">
            <h2>Quiz Généré</h2>
            <div className="quiz-content">
                {data.content.split('\n').map((line, index) => (
                    <p key={index}>{line}</p>
                ))}
            </div>
        </div>
    );
};

export default Results;
